 dest=root/path.strip('/')/'index.html';dest.parent.mkdir(exist_ok=True);dest.write_text(shell(f'Consultant SEO à {city} | Ecospheare Agency',f'Accompagnement SEO pour les entreprises qui ciblent {city} : stratégie, contenus, conversion et simulateur de potentiel. Échangez avec Ecospheare.',path,body))
